class Solution {
    public:int countPairs(vector<int>& nums,int target){
        sort(nums.begin(),nums.end());
        int left=0,right=nums.size()-1,answer=0;
        while(left<right)if(nums[left]+nums[right]<target){
            answer+=right-left;
            ++left;
        }else --right;
        return answer;
